[CmdletBinding()]
param(
  [string]$OpenOcdBin = "D:\Develop\xpack-openocd-0.12.0-7\bin\openocd.exe",
  [string]$OpenOcdScripts = "D:\Develop\xpack-openocd-0.12.0-7\openocd\scripts",
  [string]$HexPath = "$env:TEMP\openvela-debug\nuttx.hex",
  [switch]$Build
)

$ErrorActionPreference = "Stop"

if ($Build) {
  & "$PSScriptRoot\windows_build_openvela.ps1"
  if ($LASTEXITCODE -ne 0) {
    exit $LASTEXITCODE
  }
}

if (-not (Test-Path -LiteralPath $OpenOcdBin)) {
  throw "OpenOCD was not found: $OpenOcdBin"
}

if (-not (Test-Path -LiteralPath $OpenOcdScripts)) {
  throw "OpenOCD scripts directory was not found: $OpenOcdScripts"
}

if (-not (Test-Path -LiteralPath $HexPath)) {
  throw "Firmware hex was not found: $HexPath. Run scripts\windows_build_openvela.ps1 first."
}

$resolvedHex = (Resolve-Path -LiteralPath $HexPath).Path -replace "\\", "/"

& $OpenOcdBin `
  -s $OpenOcdScripts `
  -f interface/stlink.cfg `
  -f target/stm32h7x.cfg `
  -c "transport select swd" `
  -c "program $resolvedHex verify reset exit"

if ($LASTEXITCODE -ne 0) {
  exit $LASTEXITCODE
}

