	bool "Contest 2026 team 004 first led app"
	default n
	---help---
		Enable the first led for contest 2026 team 004 hello app demo.
############################################################################
# Contest 2026 team 000 hello app - Makefile
############################################################################

include $(APPDIR)/Make.defs

PROGNAME  = first_led
PRIORITY  = SCHED_PRIORITY_DEFAULT
STACKSIZE = 2048
MODULE    = $(CONFIG_LVX_USE_DEMO_CONTEST2026_004_HELLO_APP)

MAINSRC = hello_app_main.c

include $(APPDIR)/Application.mk
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <unistd.h>

#include <arch/board/board.h>
#include <nuttx/board.h>

/* Blink the board's first user LED through the NuttX board LED API.
 */

#define FIRST_LED BOARD_LED_GREEN

int main(int argc, char *argv[])
{
  uint32_t nleds = board_userled_initialize();

  if (nleds == 0)
    {
      printf("first_led: no user LEDs available\n");
      return 1;
    }
  for (; ; )
    {
      board_userled(FIRST_LED, true);
      usleep(500 * 1000);

      board_userled(FIRST_LED, false);
      usleep(500 * 1000);
    }
}

